<style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Arial,Helvetica,sans-serif;color:#050505;font-size:12px}body{background:#fff}a{color:#004c9f;text-decoration:none}a:hover{text-decoration:underline}.top-edge{display:none}.masthead{height:80px;background:#0b3049;color:#e4e7eb;display:flex;align-items:center;padding-left:16px;gap:13px}.usflag{width:90px;height:47px;position:relative;flex-shrink:0;background:repeating-linear-gradient(to bottom,#b22234 0px,#b22234 3.62px,#fff 3.62px,#fff 7.24px);border:1px solid #e5e5e5}.usflag:before{content:'★ ★ ★ ★ ★\\A ★ ★ ★ ★\\A ★ ★ ★ ★ ★\\A ★ ★ ★ ★';white-space:pre;position:absolute;left:0;top:0;width:38px;height:26px;line-height:6px;font-size:5px;color:white;background:#3c3b6e;text-align:center}.seal{width:73px;height:73px;flex-shrink:0;border:2px solid #d0b469;border-radius:50%;background:#f5f0e5;display:flex;align-items:center;justify-content:center;position:relative;color:#153750}.seal span{font: bold 30px Georgia,serif;color:#234861}.brand h1{color:#e1e5e9;font-family:Georgia,'Times New Roman',serif;font-weight:bold;font-size:29px;line-height:34px;margin:0}.brand .sub{color:#cdd6df;font-family:Georgia,'Times New Roman',serif;font-size:15px;margin-top:3px}.workspace{display:flex;min-height:421px;max-width:776px}.intro{width:250px;min-width:250px;background:#fafafa;border-right:1px dotted #999;position:relative;padding:18px 19px 75px 20px;overflow:hidden}.intro h2{font-family:Georgia,'Times New Roman',serif;color:#001b60;font-size:27px;font-weight:normal;margin:0 0 20px}.intro p{font-size:12px;line-height:14px;margin:0 0 15px}.intro .map-art{position:absolute;left:10px;bottom:0;width:215px;height:78px;opacity:.65;background:radial-gradient(ellipse at 18% 90%,#c7e4f2 0 14%,transparent 15%),radial-gradient(ellipse at 56% 65%,#c7e4f2 0 19%,transparent 20%),radial-gradient(ellipse at 70% 85%,#c7e4f2 0 17%,transparent 18%);clip-path:polygon(0 12%,38% 12%,46% 25%,81% 10%,60% 42%,100% 100%,0 100%)}.content{width:526px;flex-shrink:0}.strip{height:59px;display:flex;align-items:stretch;overflow:hidden}.strip-label{width:100px;background:#142c52;color:#fff;display:flex;justify-content:center;align-items:flex-start;padding-top:16px;font:bold 14px Georgia,serif;border-right:5px solid #a52a22}.strip-pic{flex:1;background-image:url('data:image/png;base64,');background-size:cover;background-position:center}.links{padding:4px 0 0 8px}.links h3{font: bold 14px Georgia,'Times New Roman',serif;color:#8a1a06;margin:0 0 5px;border-bottom:1px dotted #ddd;padding:0 0 3px}.links ul{list-style:none;margin:0;padding:0}.links li{height:30px;display:flex;align-items:center;gap:7px;padding-left:6px}.arrow{font-size:15px;color:#4b819f;line-height:1}.links a{font-size:12px;font-weight:600}.links .immigrant{margin-top:8px}.footer{height:67px;box-shadow:inset 0 12px 24px #ccc;background:linear-gradient(#ccc,#f0f0f0);border-top:1px solid #c4c4c4;display:flex;align-items:center;padding:12px 6px;gap:12px}.footer-icon{height:42px;width:42px;border-radius:50%;background:#123f82;border:3px dotted white;color:white;text-align:center;line-height:35px;font:bold 27px Georgia,serif}.footer-copy{padding-left:12px;border-left:1px solid #999;font-size:11px;line-height:12px}.footer-copy a{text-decoration:underline}.panel-inner{width:min(510px,100%);background:#fff;border:2px solid #23475d;box-shadow:0 10px 28px #0005}.panel-header{background:#0b3049;color:white;padding:14px 18px;font:bold 19px Georgia,serif;display:flex;justify-content:space-between;align-items:center}.panel-header button{cursor:pointer;background:none;border:0;color:#fff;font-size:26px}.panel-body{padding:20px;font-size:13px}.panel-body p{line-height:1.5}.panel-body label{display:block;font-weight:bold;margin:13px 0 5px}.panel-body input,.panel-body select{width:100%;padding:9px;border:1px solid #a9b2b9}.panel-body .submit{background:#124669;color:#fff;border:0;padding:10px 17px;margin-top:17px;cursor:pointer}.panel-body .result{margin-top:16px;padding:15px;border:1px solid #b7c5ce;background:#f2f6f9}.footline{padding:10px 20px;color:#555;border-top:1px solid #ddd;font-size:11px}@media(max-width:780px){.brand h1{font-size:clamp(16px,3.8vw,29px)}.brand .sub{font-size:11px}.masthead{gap:7px;padding-left:8px}.seal{width:58px;height:58px}.usflag{width:67px;height:36px}.workspace{max-width:100%;min-height:450px}.intro{width:32%;min-width:0;padding:16px 10px 65px}.content{width:68%;flex-shrink:1}.intro h2{font-size:23px}.strip-label{width:20%}.links a{font-size:11px}.links li{height:auto;min-height:30px}}@media(max-width:500px){.masthead{height:75px}.seal{display:none}.intro{width:38%}.content{width:62%}.links{padding-left:4px}.intro p{font-size:10px;line-height:12px}.links a{font-size:10px}.strip-label{font-size:11px}.footer{height:auto;min-height:70px}}

/* Reference-matched header graphics and type */
.masthead{gap:12px;padding-left:17px}
.usflag{display:block;width:90px;height:48px;object-fit:fill;border:0;position:static;background:none}
