@media(max-width:600px){.masthead{gap:7px;padding-left:8px}.usflag{width:60px;height:34px}.seal{width:48px;height:48px}.brand h1{font-size:clamp(15px,3.5vw,24px);line-height:1.15}.brand .sub{font-size:10px}.intro{width:39%;padding:14px 9px 65px}.content{width:61%}.links a{font-size:10px}.links li{min-height:32px;height:auto}.intro p{font-size:10px;line-height:12px}.strip-label{font-size:11px}}
